using sv_7c4feddecdad431e9a8df833d6c45e00.Client.Services;

namespace sv_7c4feddecdad431e9a8df833d6c45e00.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            "PKG-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 6, 12, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 7, 8, 0, 0, TimeSpan.Zero), "Package picked up"),
                new(new DateTimeOffset(2026, 6, 8, 14, 30, 0, TimeSpan.Zero), "Arrived at sorting facility"),
                new(new DateTimeOffset(2026, 6, 9, 6, 15, 0, TimeSpan.Zero), "Departed Memphis hub"),
            }),
        ["PKG-002"] = new ShipmentDetails(
            "PKG-002",
            "Delivered",
            "Seattle, WA",
            new DateTimeOffset(2026, 6, 8, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 5, 9, 0, 0, TimeSpan.Zero), "Package picked up"),
                new(new DateTimeOffset(2026, 6, 6, 11, 0, 0, TimeSpan.Zero), "In transit"),
                new(new DateTimeOffset(2026, 6, 7, 16, 45, 0, TimeSpan.Zero), "Out for delivery"),
                new(new DateTimeOffset(2026, 6, 7, 18, 20, 0, TimeSpan.Zero), "Delivered"),
            }),
        ["PKG-003"] = new ShipmentDetails(
            "PKG-003",
            "Processing",
            "Los Angeles, CA",
            new DateTimeOffset(2026, 6, 15, 10, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 9, 0, 30, 0, TimeSpan.Zero), "Label created"),
            }),
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment '{trackingNumber}' not found.");
    }
}

